import Foundation
public struct ApplicationDescriptor: Codable { public let id:String; public let category:String; public let upstream:String; public let spdx:String; public let platforms:[String]; public let languages:[String]; public let integration:String; public let sandbox:String; public init(id:String,category:String,upstream:String,spdx:String,platforms:[String],languages:[String],integration:String,sandbox:String){self.id=id;self.category=category;self.upstream=upstream;self.spdx=spdx;self.platforms=platforms;self.languages=languages;self.integration=integration;self.sandbox=sandbox} }
